INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-031', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 31 题', '在双缝干涉实验中，单色光源 $S_{0}$ 到两缝 $S_{1}$ 和 $S_{2}$ 的距离分别为 $l_{1}$ 和 $l_{2}$ ，并且 $l_{2}-l_{1}=3\lambda$ ，λ为入射光的波长，双缝之间的距离为 $d$ ，双缝到屏幕的距离为 $D\,(D\gg d)$ ，如图。求：

(1)零级明纹到屏幕中央 $O$ 点的距离。

(2)相邻明条纹间的距离。', '[]'::jsonb, '$x_0=-\frac{D\lambda}{3d}$; $\Delta x=\frac{D\lambda}{d}$', '[]'::jsonb, NULL, NULL, NULL, '光源到两缝的光程差 $\delta_0=l_2-l_1=\lambda/3$ 使中央条纹向 $S_2$ 方向移动。零级明纹满足 $\delta_0+dx/D=0$，$x_0=-D\lambda/(3d)$。条纹间距不变，$\Delta x=D\lambda/d$。', NULL, NULL, '/physics/q074.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-032', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 32 题', '双缝干涉实验装置如图所示，双缝与屏之间的距离 $D=120\,\mathrm{cm}$ ，两缝之间的距离 d=0.50mm，用波长 $\lambda=50 0 \mathrm{nm}\big( \mathrm{nm}=10^{-9}\mathrm{m}\big )$ 的单色光垂直照射双缝。

(1)求原点 $O$ (零级明条纹所在处)上方的第五级明条纹的坐标 x；

(2)如果用厚度 $l=1.0\times10^{-2}\,\mathrm{mm}$ ，折射率 $n {=}1.58$ 的透明薄膜复盖在图中的 $S_{1}$ 缝后面，求上述第五级明条纹的坐标 $x^{\prime},$ 。', '[]'::jsonb, '$x=6.0\,\mathrm{mm}$; $x''=-3.6\,\mathrm{cm}$', '[]'::jsonb, NULL, NULL, NULL, '（1）$x=kD\lambda/d=5\times1.2\times500\times10^{-9}/(0.5\times10^{-3})=6.0\times10^{-3}\,\mathrm{m}=6.0\,\mathrm{mm}$。（2）覆盖薄膜产生附加光程差 $\Delta=(n-1)l=0.58\times10^{-2}\,\mathrm{mm}=5.8\,\mathrm{\mu m}=11.6\lambda$。第五级明纹位置 $x''=x-(D/d)\Delta\approx-3.6\,\mathrm{cm}$。', NULL, NULL, '/physics/q075.jpg', 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-quiz-033', 'p1b-m2-quiz', 'physics-b-1', 'p1b-m2', 4, '第 33 题', '折射率为 1.60 的两块标准平面玻璃板之间形成一个劈形膜(劈尖角 θ 很小)。用波长 $\lambda=60 0 \mathrm{nm}\big( \mathrm{nm}=10^{-9}\mathrm{m}\big )$ 的单色光垂直入射，产生等厚干涉条纹。假如在劈形膜内充满 n=1.40 的液体时的相邻明纹间距比劈形膜内空气时的间距缩小 $\Delta l=0.5 \mathrm{mm}$ ，那么劈尖角θ应是多少？', '[]'::jsonb, '$\theta\approx1.7\times10^{-4}\,\mathrm{rad}$', '[]'::jsonb, NULL, NULL, NULL, '明纹间距 $l=\lambda/(2n\theta)$。空气时 $l_0=\lambda/(2\theta)$，液体时 $l=\lambda/(2n\theta)$。$\Delta l=l_0-l=\frac{\lambda}{2\theta}(1-\frac{1}{n})$。解得 $\theta=\frac{\lambda}{2\Delta l}(1-\frac{1}{n})=\frac{600\times10^{-9}}{2\times0.5\times10^{-3}}\times\frac{0.4}{1.4}\approx1.7\times10^{-4}\,\mathrm{rad}$。', NULL, NULL, NULL, 1, '["波动光学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
